      en: ["Latgalian tribes", "Ancient fortification", "Defensive post", "Archaeological site"],
      es: ["Tribus latgalianas", "Fortificación antigua", "Puesto de defensa", "Sitio arqueológico"],
      pt: ["Tribos latigalianas", "Fortificação antiga", "Posto de defesa", "Sítio arqueológico"],
      fr: ["Tribus latgaliennes", "Fortification antique", "Poste de défense", "Site archéologique"],
